const input = $json ?? {};
const executionId = String(input.execution_id ?? $execution.id ?? 'unknown');
const correlationId = String(input.correlation_id ?? `REQ-${executionId}`);
const eventName = String(input.event_name ?? 'workflow_event');
const loggedAt = String(input.logged_at ?? input.request_timestamp ?? new Date().toISOString());
const eventId = `${loggedAt}#${executionId}#${eventName}`;
const startedAt = Date.parse(String(input.request_timestamp ?? ''));
const durationMs = Number.isFinite(startedAt) ? Math.max(0, Date.now() - startedAt) : Number(input.duration_ms ?? 0);
return {json:{
  ...input, correlation_id:correlationId, execution_id:executionId,
  event_name:eventName, logged_at:loggedAt, event_id:eventId,
  workflow_name:String(input.workflow_name ?? 'unknown'),
  status:String(input.status ?? input.log_status ?? 'RECORDED'),
  duration_ms:durationMs
}};

const original = $('When Executed by Another Workflow').first().json;
const built = $('Code - Build Structured Log Event').first().json;
return [{json:{...original,observability_event_id:built.event_id,observability_persisted:true}}];
